 for(let i=0;i<count;i++){const day=new Date(Date.parse(start+'T12:00:00Z')+i*86400000).toISOString().slice(0,10),row=map.get(day);days.push({day,income:row?row.income:0,expense:row?row.expense:0,net:row?row.net:0});}
