 const paths=series.map(([key])=>'<path class="pulse-line line-'+key+'" d="'+days.map((day,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+y(day[key]).toFixed(1)).join(' ')+'"/>').join('');
