 const table='<details class="chart-data"><summary>Ver valores diários em tabela</summary><div class="chart-table-wrap"><table class="chart-table"><thead><tr><th>Dia</th><th>Entradas</th><th>Despesas</th><th>Resultado</th></tr></thead><tbody>'+days.map((day)=>'<tr><th scope="row">'+dateBR(day.day)+'</th><td>'+money(day.income)+'</td><td>'+money(day.expense)+'</td><td>'+money(day.net)+'</td></tr>').join('')+'</tbody></table></div></details>';
