 const actions=[];
 if(role==='reception'){if(item.status==='scheduled')actions.push('<button class="inline-button" data-action="appointment-status" data-status="confirmed" data-id="'+item.id+'">Confirmar</button>');if(['scheduled','confirmed'].includes(item.status))actions.push('<button class="inline-button" data-action="appointment-status" data-status="completed" data-id="'+item.id+'">Concluir</button>');if(item.status==='completed'&&item.payment_status!=='paid')actions.push('<button class="inline-button" data-action="receive-appointment" data-id="'+item.id+'">Registrar recebimento</button>');}
